import{_ as a,C as r,c as n,o as d,a3 as e,G as o}from"./chunks/framework.Dokpd4od.js";const m=JSON.parse('{"title":"Website overview","description":"","frontmatter":{},"headers":[],"relativePath":"master/website/get-started/website-overview.md","filePath":"master/website/get-started/website-overview.md","lastUpdated":1793074831000}'),i={name:"master/website/get-started/website-overview.md"};function g(l,t,h,p,c,b){const s=r("ImagePopup");return d(),n("div",null,[t[0]||(t[0]=e('<h1 id="website-overview" tabindex="-1">Website overview <a class="header-anchor" href="#website-overview" aria-label="Permalink to &quot;Website overview&quot;">​</a></h1><p>The Website app has one admin menu bar with a few menus and a dashboard. Each menu controls one part of your public site. This page shows every menu, the dashboard and a map from admin option to public result.</p><blockquote><p><strong>In simple words:</strong> Know which admin menu changes which part of the site, and you will never hunt for a setting.</p></blockquote><p>Open the app from the app switcher, then choose <strong>Website</strong>. No setting turns Website on or off. You see the menus your plugins and permissions allow.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Blog Posts</strong> and <strong>Configurations</strong> need the <strong>Blogs</strong> plugin. Customer portal actions need the customer portal.</p></div><h2 id="admin-menus" tabindex="-1">Admin menus <a class="header-anchor" href="#admin-menus" aria-label="Permalink to &quot;Admin menus&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu</th><th>Path</th><th>Use it to</th></tr></thead><tbody><tr><td><strong>Dashboard</strong></td><td><code>Website → Dashboard</code></td><td>See page and blog numbers and charts</td></tr><tr><td><strong>Blog Posts</strong></td><td><code>Website → Blog Posts</code></td><td>Write and publish posts. See <a href="./../blog/blog-posts.html">Blog posts</a></td></tr><tr><td><strong>Pages</strong></td><td><code>Website → Pages</code></td><td>Build pages and choose header and footer menus. See <a href="./../pages/create-a-page.html">Create a page</a></td></tr><tr><td><strong>Customers</strong></td><td><code>Website → Customers</code></td><td>View customer records and their portal access. See <a href="./../customers/customers.html">Customers</a></td></tr><tr><td><strong>Configurations</strong></td><td><code>Website → Configurations</code></td><td>Manage <strong>Categories</strong> and <strong>Tags</strong>. See <a href="./../blog/categories-and-tags.html">Categories and tags</a></td></tr><tr><td><strong>Settings</strong></td><td><code>Website → Settings → Manage Contacts</code></td><td>Set email, phone and social links. See <a href="./../settings/manage-contacts.html">Manage contacts</a></td></tr></tbody></table>',7)),o(s,{src:"/images1/website/ov_top_bar.png",alt:"Website app menu bar showing Blog Posts, Pages, Customers, Configurations and Settings menus"}),t[1]||(t[1]=e('<p>Every list and form has a <strong>Locale</strong> switcher with English, Arabic, Spanish, Portuguese (Brazil) and French. Titles, content and meta fields can be translated.</p><h2 id="the-dashboard" tabindex="-1">The dashboard <a class="header-anchor" href="#the-dashboard" aria-label="Permalink to &quot;The dashboard&quot;">​</a></h2><p>Open <code>Website → Dashboard</code>. Two filters sit at the top.</p><p><strong><em>Date Range:</em></strong> Limits the blog numbers and charts to a period.</p><p><strong><em>Author:</em></strong> Shows blog numbers for one author. The default is <strong>All Author</strong>.</p><h3 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Stat</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Total Pages</strong></td><td>All pages</td></tr><tr><td><strong>Total Publish Pages</strong></td><td>Pages that are live</td></tr><tr><td><strong>Total Draft Pages</strong></td><td>Pages not yet published</td></tr><tr><td><strong>Total Blogs</strong></td><td>All posts</td></tr><tr><td><strong>Total Publish Blogs</strong></td><td>Posts that are live</td></tr><tr><td><strong>Total Draft Blogs</strong></td><td>Posts not yet published</td></tr></tbody></table><p>The page counts ignore the filters. The blog counts follow them.</p>',8)),o(s,{src:"/images1/website/dash_stats.png",alt:"Dashboard filters Date Range and Author with the six stat tiles"}),t[2]||(t[2]=e('<h3 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to &quot;Widgets&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Widget</th><th>Shows</th></tr></thead><tbody><tr><td><strong>Published Blogs by Month</strong></td><td>Posts published each month</td></tr><tr><td><strong>Blogs by Category</strong></td><td>Posts per category</td></tr><tr><td><strong>Top 10 Authors by Blog Counts</strong></td><td>Most active authors</td></tr><tr><td><strong>Blogs: Published vs Draft</strong></td><td>The share of live and draft posts</td></tr><tr><td><strong>Top Categories Table</strong></td><td>Categories ranked by post count</td></tr><tr><td><strong>Recent Blogs Table</strong></td><td>The latest posts</td></tr></tbody></table>',2)),o(s,{src:"/images1/website/dash_widgets.png",alt:"Dashboard charts and the Top Categories and Recent Blogs tables"}),t[3]||(t[3]=e(`<h2 id="admin-option-to-public-site" tabindex="-1">Admin option to public site <a class="header-anchor" href="#admin-option-to-public-site" aria-label="Permalink to &quot;Admin option to public site&quot;">​</a></h2><p>This is the map. Each row names an admin option and the part of the public site it changes.</p><table tabindex="0"><thead><tr><th>Public site part</th><th>Controlled by</th><th>Where</th></tr></thead><tbody><tr><td><strong>Header menu</strong></td><td><strong>Is Visible Header Menu</strong> on a page</td><td><code>Website → Pages</code></td></tr><tr><td><strong>Footer Useful Links</strong></td><td>Home plus pages with <strong>Is Visible Footer Menu</strong></td><td><code>Website → Pages</code></td></tr><tr><td><strong>Home</strong> (<code>/</code>)</td><td>The page with the slug <code>home</code></td><td><code>Website → Pages</code></td></tr><tr><td>Any page (<code>/pages/{slug}</code>)</td><td>Page content, once published</td><td><code>Website → Pages</code></td></tr><tr><td><strong>Blog list</strong> (<code>/blog</code>)</td><td>Published posts, categories and tags</td><td><code>Website → Blog Posts</code>, <code>Configurations</code></td></tr><tr><td><strong>Footer Contact Us</strong></td><td><strong>Email</strong> and <strong>Phone</strong></td><td><code>Website → Settings → Manage Contacts</code></td></tr><tr><td><strong>Footer Follow Us</strong> icons</td><td>Social links</td><td><code>Website → Settings → Manage Contacts</code></td></tr><tr><td><strong>Language list</strong></td><td>The built in languages, shown in the site header</td><td>Fixed</td></tr><tr><td><strong>Login and Register</strong></td><td>Customer accounts</td><td><a href="./../customers/portal-and-sign-in.html">Portal and sign in</a></td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pages ─────────► header menu, footer Useful Links, Home, /pages/{slug}</span></span>
<span class="line"><span>Blog Posts ────► /blog and post pages</span></span>
<span class="line"><span>Manage Contacts ► footer Contact Us and Follow Us</span></span>
<span class="line"><span>Customers ─────► login and register</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A page must be published to appear. A draft page gives a not found error to visitors. See <a href="./../pages/publish-and-draft.html">Publish and draft</a>.</p></div><h2 id="what-the-visitor-sees" tabindex="-1">What the visitor sees <a class="header-anchor" href="#what-the-visitor-sees" aria-label="Permalink to &quot;What the visitor sees&quot;">​</a></h2><p>The site header shows Home, your header pages, Blog, a search box, a language list, <strong>Login</strong> and <strong>Register</strong>. The footer shows a short fixed description, <strong>Useful Links</strong>, <strong>Contact Us</strong>, <strong>Follow Us</strong> and a copyright line.</p>`,7)),o(s,{src:"/images1/website/site_top_bar_footer.png",alt:"Public home page with the site header: Home, header pages, Blog, search, language list, Login and Register"}),t[4]||(t[4]=e('<h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">Website</a></li><li><a href="./first-steps.html">First steps</a></li><li><a href="./../pages/publish-and-draft.html">Publish and draft</a></li><li><a href="./../../getting-started/contacts/contacts.html">Contacts</a></li></ul>',2))])}const f=a(i,[["render",g]]);export{m as __pageData,f as default};
